package com.bank.marketdata.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "stock_prices")
public class StockPrice {

    @Id
    private String symbol;

    @Column(name = "company_name", nullable = false)
    private String companyName;

    @Column(name = "current_price", nullable = false)
    private BigDecimal currentPrice;

    @Column(name = "day_high")
    private BigDecimal dayHigh;

    @Column(name = "day_low")
    private BigDecimal dayLow;

    private Long volume;

    @Column(name = "last_updated")
    private LocalDateTime lastUpdated;

    protected StockPrice() {}

    public void updatePrice(BigDecimal newPrice) {
        this.currentPrice = newPrice;
        if (dayHigh == null || newPrice.compareTo(dayHigh) > 0) this.dayHigh = newPrice;
        if (dayLow == null || newPrice.compareTo(dayLow) < 0) this.dayLow = newPrice;
        this.lastUpdated = LocalDateTime.now();
    }

    public String getSymbol() { return symbol; }
    public String getCompanyName() { return companyName; }
    public BigDecimal getCurrentPrice() { return currentPrice; }
    public BigDecimal getDayHigh() { return dayHigh; }
    public BigDecimal getDayLow() { return dayLow; }
    public Long getVolume() { return volume; }
    public LocalDateTime getLastUpdated() { return lastUpdated; }
}
