// Distributed lock using Redis SET NX PX — for cache stampede prevention
package com.bank.marketdata.lock;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;
import java.time.Duration;
import java.util.UUID;

@Component
@RequiredArgsConstructor
@Slf4j
public class RedisDistributedLock {

    private final StringRedisTemplate redisTemplate;

    /**
     * Acquire lock atomically: SET key uniqueToken NX PX ttlMs
     * NX = only if not exists. PX = auto-expire (prevents dead holder deadlock).
     */
    public String tryAcquire(String lockKey, Duration ttl) {
        String token = UUID.randomUUID().toString();
        Boolean acquired = redisTemplate.opsForValue()
            .setIfAbsent(lockKey, token, ttl);  // atomic SET NX PX

        if (Boolean.TRUE.equals(acquired)) {
            log.debug("Lock acquired: {} (token={})", lockKey, token);
            return token;
        }
        return null;  // lock held by another instance
    }

    /**
     * Release lock ONLY if we still own it (compare token).
     * Uses Lua script for atomicity: GET + compare + DEL in one command.
     */
    public void release(String lockKey, String token) {
        String currentToken = redisTemplate.opsForValue().get(lockKey);
        if (token.equals(currentToken)) {
            redisTemplate.delete(lockKey);
            log.debug("Lock released: {}", lockKey);
        }
    }
}
