package com.bank.marketdata.service;

import com.bank.marketdata.dto.PriceResponse;
import com.bank.marketdata.lock.RedisDistributedLock;
import com.bank.marketdata.model.StockPrice;
import com.bank.marketdata.repository.PriceRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.cache.annotation.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.time.Duration;

@Service
@RequiredArgsConstructor
@Slf4j
public class PriceService {

    private final PriceRepository priceRepo;
    private final RedisDistributedLock distributedLock;

    /**
     * @Cacheable: check Redis first. If cached → return immediately (no DB hit).
     * If not cached → execute method, store result in Redis, return.
     * Key: "prices::RELIANCE" (cache name + SpEL key)
     */
    @Cacheable(value = "prices", key = "#symbol")
    public PriceResponse getPrice(String symbol) {
        log.info("CACHE MISS: fetching {} from database", symbol);
        StockPrice price = priceRepo.findById(symbol)
            .orElseThrow(() -> new IllegalArgumentException("Symbol not found: " + symbol));
        return PriceResponse.from(price, false);
    }

    /**
     * @CachePut: ALWAYS executes method and updates cache with new value.
     * Used after a price update — cache now has the fresh value.
     */
    @CachePut(value = "prices", key = "#symbol")
    @Transactional
    public PriceResponse updatePrice(String symbol, BigDecimal newPrice) {
        log.info("Updating price: {} → Rs.{}", symbol, newPrice);
        StockPrice price = priceRepo.findById(symbol)
            .orElseThrow(() -> new IllegalArgumentException("Symbol not found: " + symbol));
        price.updatePrice(newPrice);
        priceRepo.save(price);
        return PriceResponse.from(price, false);
    }

    /**
     * @CacheEvict: removes the cached entry. Next read will hit DB.
     * Used when you want the next request to get fresh data.
     */
    @CacheEvict(value = "prices", key = "#symbol")
    public void evictPrice(String symbol) {
        log.info("Cache evicted: {}", symbol);
    }

    @CacheEvict(value = "prices", allEntries = true)
    public void evictAll() {
        log.info("All price cache entries evicted");
    }

    /**
     * Stampede-safe fetch: distributed lock prevents multiple instances
     * from fetching the same missing key simultaneously.
     */
    public PriceResponse getPriceWithStampedeProtection(String symbol) {
        // Try cache first (manual check — not using @Cacheable for stampede control)
        PriceResponse cached = getFromCacheDirectly(symbol);
        if (cached != null) return cached;

        // Cache miss — acquire distributed lock (only ONE instance fetches)
        String lockKey = "lock:price:" + symbol;
        String token = distributedLock.tryAcquire(lockKey, Duration.ofSeconds(5));

        if (token != null) {
            try {
                // Double-check: another thread may have populated cache while we waited for lock
                cached = getFromCacheDirectly(symbol);
                if (cached != null) return cached;

                // We hold the lock — fetch from DB and populate cache
                log.info("STAMPEDE LOCK: fetching {} (single-flight)", symbol);
                return getPrice(symbol);  // triggers @Cacheable
            } finally {
                distributedLock.release(lockKey, token);
            }
        } else {
            // Lock held by another instance — wait briefly and retry from cache
            log.debug("STAMPEDE WAIT: {} locked by another instance, retrying cache", symbol);
            try { Thread.sleep(100); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            cached = getFromCacheDirectly(symbol);
            return cached != null ? cached : getPrice(symbol);
        }
    }

    private PriceResponse getFromCacheDirectly(String symbol) {
        // In real app: use RedisTemplate.opsForValue().get("prices::" + symbol)
        return null; // simplified
    }
}
