package com.bank.marketdata.controller;

import com.bank.marketdata.dto.PriceResponse;
import com.bank.marketdata.service.PriceService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/prices")
@RequiredArgsConstructor
public class PriceController {

    private final PriceService priceService;

    @GetMapping("/{symbol}")
    public PriceResponse getPrice(@PathVariable String symbol) {
        return priceService.getPrice(symbol);
    }

    @PutMapping("/{symbol}")
    public PriceResponse updatePrice(@PathVariable String symbol,
                                      @RequestParam BigDecimal price) {
        return priceService.updatePrice(symbol, price);
    }

    @DeleteMapping("/{symbol}/cache")
    public void evictCache(@PathVariable String symbol) {
        priceService.evictPrice(symbol);
    }
}
